use super::*;
#[test]
fn document_buffer_replays_neutral_rename_and_uncertain_settlement(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 let root=std::path::PathBuf::from(std::env::var_os("SEMIO_TEST_ARTIFACT_DIR").expect("owned buffer artifacts required")).join(format!("buffer{}",std::process::id()));std::fs::create_dir_all(&root).unwrap();std::fs::write(root.join("base"),"kept 🧪").unwrap();let workspace=crate::Workspace::new(&root).unwrap();let document=workspace.load("base",&std::sync::atomic::AtomicBool::new(false),&mut |_|{}).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let mut current=DocumentBuffer{document:document.clone(),read_only:false,recovery:None,dirty:row["dirty"].as_bool().unwrap(),generation:7,discard_confirmation:true};current.document.path=row["path"].as_str().unwrap().into();let roots=row["roots"].as_array().unwrap().iter().map(|value|value.as_str().unwrap().to_owned()).collect::<Vec<_>>();let changed=if row["operation"]=="uncertain"{current.mark_uncertain(&roots,row["recovery"].as_str())}else{let mut loaded=document.clone();loaded.path=row["destination"].as_str().unwrap().into();current.remap(&roots[0],row["destination"].as_str().unwrap(),row["loaded"].as_bool().unwrap().then_some(&loaded))};if row["reloadRefused"].as_bool().unwrap(){current.record_failure(&crate::Error{kind:crate::ErrorKind::NotFile,path:current.document.path.clone(),detail:"reload refused".into(),recovery_path:None});}assert_eq!(changed,row["changed"].as_bool().unwrap(),"{}",row["id"]);assert_eq!(current.document.path,row["expectedPath"].as_str().unwrap());assert_eq!(current.read_only,row["readOnly"].as_bool().unwrap());assert_eq!(current.recovery.as_deref(),row["expectedRecovery"].as_str());assert_eq!(current.document.text,"kept 🧪");assert_eq!(current.dirty,row["dirty"].as_bool().unwrap());assert_eq!(current.generation,7);}
 drop(workspace);std::fs::remove_dir_all(root).unwrap();
}
